// Generate lib/api/ui-schemas.d.ts from the UI form specs exported by
// api/scripts/dump_openapi.py into api/ui_schemas_out/*.json. Do not edit the output.
import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { compile } from "json-schema-to-typescript";

const SRC = "../api/ui_schemas_out";
const OUT = "lib/api/ui-schemas.d.ts";
const pascal = (s) => s.replace(/(^|_)(\w)/g, (_, __, c) => c.toUpperCase());

const files = existsSync(SRC) ? readdirSync(SRC).filter((f) => f.endsWith(".json")).sort() : [];
const parts = ["/* GENERATED by scripts/gen-ui-types.mjs: do not edit. */", ""];
const names = [];

for (const file of files) {
  const spec = JSON.parse(readFileSync(`${SRC}/${file}`, "utf8"));
  const name = `${pascal(spec.name)}Values`;
  names.push(`  ${JSON.stringify(spec.name)}: ${name};`);
  // Titles would become separate (and duplicated) type aliases; strip them so each
  // form compiles to one self-contained interface named <Form>Values.
  const properties = Object.fromEntries(
    Object.entries(spec.schema.properties).map(([k, { title, ...rest }]) => [k, { ...rest, description: title }]));
  const schema = { ...spec.schema, title: name, properties };
  parts.push(await compile(schema, name, { bannerComment: "", additionalProperties: false }));
}
parts.push("export interface UiFormValues {", ...names, "}", "export type UiFormName = keyof UiFormValues;", "");
writeFileSync(OUT, parts.join("\n"));
console.log(`wrote ${OUT} (${files.length} specs)`);
